import{_ as t,o as a,c as n,ae as o}from"./chunks/framework.Dh1jimFm.js";const d=JSON.parse('{"title":"Navigating Segments","description":"","frontmatter":{},"headers":[],"relativePath":"editor/navigation.md","filePath":"editor/navigation.md"}'),r={name:"editor/navigation.md"};function i(s,e,l,g,m,u){return a(),n("div",null,e[0]||(e[0]=[o('<h1 id="navigating-segments" tabindex="-1">Navigating Segments <a class="header-anchor" href="#navigating-segments" aria-label="Permalink to &quot;Navigating Segments&quot;">​</a></h1><p>Supervertaler is designed for fast, memoQ-style navigation in the translation grid.</p><h2 id="moving-between-segments" tabindex="-1">Moving between segments <a class="header-anchor" href="#moving-between-segments" aria-label="Permalink to &quot;Moving between segments&quot;">​</a></h2><ul><li>Use the arrow keys to move within a cell.</li><li>When your cursor is at the <strong>top</strong> or <strong>bottom</strong> line of a cell, <strong>Up/Down</strong> can jump to the previous/next segment.</li></ul><h3 id="always-move-up-down" tabindex="-1">Always move up/down <a class="header-anchor" href="#always-move-up-down" aria-label="Permalink to &quot;Always move up/down&quot;">​</a></h3><p>If you want to move between segments regardless of where the cursor is inside the cell:</p><ul><li><strong>Alt+Up</strong> → previous segment</li><li><strong>Alt+Down</strong> → next segment</li></ul><h3 id="jump-to-a-segment" tabindex="-1">Jump to a segment <a class="header-anchor" href="#jump-to-a-segment" aria-label="Permalink to &quot;Jump to a segment&quot;">​</a></h3><ul><li><strong>Ctrl+G</strong> opens <strong>Go to Segment</strong>.</li><li>Type a segment number and press Enter.</li></ul><h3 id="jump-to-start-end" tabindex="-1">Jump to start/end <a class="header-anchor" href="#jump-to-start-end" aria-label="Permalink to &quot;Jump to start/end&quot;">​</a></h3><ul><li><strong>Ctrl+Home</strong> → first segment</li><li><strong>Ctrl+End</strong> → last segment</li></ul><h3 id="tab-between-source-target" tabindex="-1">Tab between Source/Target <a class="header-anchor" href="#tab-between-source-target" aria-label="Permalink to &quot;Tab between Source/Target&quot;">​</a></h3><ul><li><strong>Tab</strong> cycles between the Source and Target cell on the same row.</li><li><strong>Ctrl+Tab</strong> inserts a literal tab character inside the text.</li></ul><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><p>If your project is large, you can enable pagination and move page-by-page.</p><ul><li>See: <a href="./pagination.html">Pagination</a></li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Keep one hand on the keyboard for speed: navigate, edit, confirm, repeat.</li><li>If you work in a CAT tool daily, customize shortcuts to match your muscle memory.</li></ul><p>See also: <a href="./keyboard-shortcuts.html">Keyboard Shortcuts</a></p>',19)]))}const p=t(r,[["render",i]]);export{d as __pageData,p as default};
